/*
 * ufs_wrap.c -- generated by tools/carve.py (S5-04): the ufs module's
 * wrapper.  _load registers the type (vfs_register, contract C4-6
 * section 3); with probe=1 it prints the level and whether
 * lbolt moved around each init call (S4-71's ufs/s5 halves).
 */
#include "sys/types.h"
#include "sys/errno.h"
#include "sys/moddefs.h"
#include "sys/amixddi.h"

extern int	ufsinit(), printf();
extern char	ufs_vfsops[];
extern long	lbolt;

static int	probe;

static int
level()
{
	unsigned short s;

	__asm__ __volatile__("movew %%sr,%0" : "=d" (s));
	return (s >> 8) & 7;
}

static void
said(what, lb)
	char *what;
	long lb;
{
	if (probe)
		printf("ufs: %s, level %d, lbolt %s\n", what, level(),
		    lbolt == lb ? "unmoved" : "MOVED");
}

/* the row's init, as vfsinit would call it */
static int
ufs_init(vswp, idx)
	char *vswp;
	int idx;
{
	long lb = lbolt;
	int r;

	said("ufsinit entered", lb);
	r = ufsinit(vswp, idx);
	said("ufsinit returned", lb);
	return r;
}

static int
ufs_load(params)
	char *params;
{
	char *p;

	for (p = params; p && *p; p++)
		if ((p == params || p[-1] == ' ') && p[0] == 'p' && p[1] == 'r' && p[2] == 'o' &&
		    p[3] == 'b' && p[4] == 'e' && p[5] == '=' && p[6] == '1')
			probe = 1;
	return vfs_register("ufs", ufs_init, (struct vfsops *)ufs_vfsops, 0L);
}

static int
ufs_unload()
{
	return EBUSY;		/* unload=never: a mounted type stays */
}

MOD_MISC_WRAPPER(ufs, ufs_load, ufs_unload, "ufs filesystem (carved)");
